#!/bin/bash
#MISE description="Vendor OpenUI's renderer into App/OpenUI/vendor and regenerate the agents' OpenUI Lang reference"
# Vendors OpenUI's prebuilt renderer into the app, and generates the OpenUI Lang reference the
# browser kit gives agents (backlog doc Browser, OpenUI tabs). Run from the repo root when bumping:
#
#   mise run vendor:openui
#
# Writes App/OpenUI/vendor/ (openui-bundle.min.js, openui-styles.css, LICENSE, VERSION) and
# Packages/PaddockCore/Sources/PaddockCore/Resources/openui-reference.md. Both are committed:
# the app never downloads anything. The bundle's tarball is checked against npm's sha512
# integrity value; the reference comes from OpenUI's own prompt generator, for the same
# react-ui version the bundle contains, so the agent writes exactly what the renderer renders.
#
# Needs node and npm (dev tools only). Compatible with the stock macOS bash 3.2.

set -euo pipefail

BUNDLE_VERSION="0.2.1"     # @openuidev/browser-bundle
REACT_UI_VERSION="0.18.1"  # @openuidev/react-ui inside that bundle (its package.json)

ROOT="$(cd "$(dirname "$0")/../../.." && pwd)"
VENDOR="$ROOT/App/OpenUI/vendor"
REFERENCE="$ROOT/Packages/PaddockCore/Sources/PaddockCore/Resources/openui-reference.md"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

echo "==> @openuidev/browser-bundle $BUNDLE_VERSION"
META="$(curl -fsSL "https://registry.npmjs.org/@openuidev/browser-bundle/$BUNDLE_VERSION")"
TARBALL="$(printf '%s' "$META" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>console.log(JSON.parse(s).dist.tarball))')"
INTEGRITY="$(printf '%s' "$META" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>console.log(JSON.parse(s).dist.integrity))')"
curl -fsSL "$TARBALL" -o "$WORK/bundle.tgz"
ACTUAL="sha512-$(openssl dgst -sha512 -binary "$WORK/bundle.tgz" | openssl base64 -A)"
if [ "$ACTUAL" != "$INTEGRITY" ]; then
  echo "integrity mismatch: npm says $INTEGRITY, the tarball is $ACTUAL" >&2
  exit 1
fi
tar -xzf "$WORK/bundle.tgz" -C "$WORK"
mkdir -p "$VENDOR"
cp "$WORK/package/dist/openui-bundle.min.js" "$WORK/package/dist/openui-styles.css" "$WORK/package/LICENSE" "$VENDOR/"
printf '@openuidev/browser-bundle %s (%s)\n' "$BUNDLE_VERSION" "$INTEGRITY" > "$VENDOR/VERSION"

echo "==> OpenUI Lang reference from @openuidev/react-ui $REACT_UI_VERSION"
( cd "$WORK" && npm init -y > /dev/null && npm install --silent --ignore-scripts --no-audit --no-fund \
    "@openuidev/react-ui@$REACT_UI_VERSION" react@19 react-dom@19 > /dev/null )
mkdir -p "$(dirname "$REFERENCE")"
( cd "$WORK" && node --input-type=module -e '
  const { openuiChatLibrary } = await import("@openuidev/react-ui/genui-lib");
  const { openuiChatPromptOptions } = await import("@openuidev/react-ui/genui-lib/prompt-options");
  process.stdout.write(openuiChatLibrary.prompt(openuiChatPromptOptions));
' ) > "$WORK/prompt.md"
{
  echo "# OpenUI Lang reference (for paddock ui)"
  echo
  echo "Generated by tools/tasks/vendor/openui.sh from @openuidev/react-ui $REACT_UI_VERSION, the library Paddock's"
  echo "renderer uses. In Paddock a document is a file you pass to \`paddock ui\`; the operator's clicks and"
  echo "form values come back through \`paddock wait\`. Paddock's own rules, which come first:"
  echo
  echo "- The tab is offline: no images, no external URLs, no \`sources\` on Card; \`@OpenUrl\` only reports the URL back to you."
  echo "- Write \`root = Card(...)\` first. Every Form has exactly one primary Button."
  echo "- Give buttons an action (\`@ToAssistant(\"label\", {key: value})\`) whose message and context tell you what was chosen."
  echo
  echo "---"
  echo
  cat "$WORK/prompt.md"
} > "$REFERENCE"
echo "wrote $VENDOR and $REFERENCE ($(wc -c < "$REFERENCE") bytes)"
